  "content": "<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Account settings</title>

  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,400..700;1,400..700&family=Source+Sans+3:wght@300..900&family=JetBrains+Mono:wght@400;500;600&display=swap" />

  <link rel="stylesheet" href="./node_modules/@taproot-ds/tokens/dist/css/tokens.css" />
  <link rel="stylesheet" href="./node_modules/@taproot-ds/tokens/dist/css/base.css" />

  <style>
    main {
      max-width: 40rem;
      margin-inline: auto;
      padding: var(--ds-primitives-space-12) var(--ds-primitives-space-6);
      display: flex;
      flex-direction: column;
      gap: var(--ds-primitives-space-10);
    }
    h1, h2, p { margin: 0; }
    section {
      display: flex;
      flex-direction: column;
      gap: var(--ds-primitives-space-4);
    }
    .supporting { color: var(--ds-semantic-color-foreground-muted); }
    form {
      display: flex;
      flex-direction: column;
      gap: var(--ds-primitives-space-5);
    }
    .actions {
      display: flex;
      flex-wrap: wrap;
      justify-content: flex-end;
      gap: var(--ds-primitives-space-3);
    }
    .danger-zone {
      padding: var(--ds-primitives-space-6);
      border: var(--ds-semantic-border-width) solid var(--ds-semantic-color-border-status-danger-default);
      border-radius: var(--ds-semantic-radius-surface);
      background: var(--ds-semantic-color-background-surface);
    }
    .danger-zone .actions { justify-content: flex-start; }
  </style>

  <script type="module">
    import { defineButton } from "./node_modules/@taproot-ds/web-components/src/button.js";
    import { defineTextField } from "./node_modules/@taproot-ds/web-components/src/text-field.js";
    import { defineDialog } from "./node_modules/@taproot-ds/web-components/src/dialog.js";
    import { defineAlert } from "./node_modules/@taproot-ds/web-components/src/alert.js";

    defineButton();
    defineTextField();
    defineDialog();
    defineAlert();

    const form = document.getElementById("profile-form");
    const nameField = document.getElementById("display-name");
    const emailField = document.getElementById("email");
    const cancelButton = document.getElementById("cancel-profile");
    const profileStatus = document.getElementById("profile-status");

    const deleteButton = document.getElementById("delete-account");
    const deleteDialog = document.getElementById("delete-dialog");
    const cancelDelete = document.getElementById("cancel-delete");
    const confirmDelete = document.getElementById("confirm-delete");
    const accountStatus = document.getElementById("account-status");

    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    function clearErrors() {
      nameField.removeAttribute("error");
      emailField.removeAttribute("error");
    }

    // Clear a field's error as soon as the person edits it.
    for (const field of [nameField, emailField]) {
      field.addEventListener("input", () => {
        field.removeAttribute("error");
        profileStatus.hidden = true;
      });
    }

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      clearErrors();
      profileStatus.hidden = true;

      const data = new FormData(form);
      const name = String(data.get("displayName") ?? "").trim();
      const email = String(data.get("email") ?? "").trim();
      let firstInvalid = null;

      if (!name) {
        nameField.setAttribute("error", "Enter a display name");
        firstInvalid ??= nameField;
      }
      if (!email) {
        emailField.setAttribute("error", "Enter an email address");
        firstInvalid ??= emailField;
      } else if (!emailPattern.test(email)) {
        emailField.setAttribute("error", "Enter an email address in the format name@example.com");
        firstInvalid ??= emailField;
      }

      if (firstInvalid) {
        firstInvalid.focus();
        return;
      }

      // Saved values become the ones Cancel restores.
      nameField.setAttribute("value", name);
      emailField.setAttribute("value", email);
      profileStatus.hidden = false;
    });

    cancelButton.addEventListener("click", () => {
      form.reset();
      clearErrors();
      profileStatus.hidden = true;
    });

    deleteButton.addEventListener("click", () => deleteDialog.showModal());
    cancelDelete.addEventListener("click", () => deleteDialog.close());
    confirmDelete.addEventListener("click", () => {
      deleteDialog.close();
      deleteButton.disabled = true;
      deleteButton.setAttribute("disabled", "");
      accountStatus.hidden = false;
    });
  </script>
</head>
<body>
  <main>
    <h1>Account settings</h1>

    <section aria-labelledby="profile-heading">
      <h2 id="profile-heading">Profile</h2>
      <p class="supporting">Change how your name appears and where we send account email.</p>

      <form id="profile-form" novalidate>
        <ds-text-field
          id="display-name"
          label="Display name"
          name="displayName"
          value="Alex Morgan"
          hint="Shown to other people on your profile and in comments."
          autocomplete="name"
          required
        ></ds-text-field>

        <ds-text-field
          id="email"
          label="Email address"
          name="email"
          type="email"
          value="alex.morgan@example.com"
          hint="Used for sign-in and account notifications."
          autocomplete="email"
          required
        ></ds-text-field>

        <div id="profile-status" hidden>
          <ds-alert variant="success" label="Changes saved" announce="polite">
            Your display name and email address are up to date.
          </ds-alert>
        </div>

        <div class="actions">
          <ds-button id="cancel-profile" type="button" variant="secondary">Cancel</ds-button>
          <ds-button type="submit" variant="primary">Save changes</ds-button>
        </div>
      </form>
    </section>

    <section class="danger-zone" aria-labelledby="danger-heading">
      <h2 id="danger-heading">Delete account</h2>
      <p>
        Deleting your account permanently removes your profile, settings, and all of your data.
        This cannot be undone.
      </p>

      <div id="account-status" hidden>
        <ds-alert variant="info" label="Account deletion requested" announce="polite">
          Your account is being deleted. You will be signed out shortly.
        </ds-alert>
      </div>

      <div class="actions">
        <ds-button id="delete-account" variant="destructive">Delete account</ds-button>
      </div>
    </section>
  </main>

  <ds-dialog
    id="delete-dialog"
    label="Delete your account?"
    description="This permanently deletes your account and all of its data. It cannot be undone."
  >
    <p>You will lose access to your profile and settings right away, and we cannot restore them.</p>
    <ds-button slot="actions" id="cancel-delete" variant="secondary">Keep account</ds-button>
    <ds-button slot="actions" id="confirm-delete" variant="destructive">Delete account</ds-button>
  </ds-dialog>
</body>
</html>
